"""Regression tests for native desktop branding generated by Flutter."""
from __future__ import annotations

import unittest

from platform_branding import (
    disable_linux_impeller,
    disable_windows_impeller,
    replace_linux_window_title,
    replace_windows_window_title,
)


class PlatformBrandingTests(unittest.TestCase):
    def test_linux_gtk_window_title(self) -> None:
        source = 'gtk_window_set_title(window, "depthvibe");'
        updated, count = replace_linux_window_title(source)
        self.assertEqual(count, 1)
        self.assertEqual(updated, 'gtk_window_set_title(window, "DepthVibe");')

    def test_linux_title_without_matching_call_is_unchanged(self) -> None:
        source = 'gtk_window_set_title(other, "depthvibe");'
        updated, count = replace_linux_window_title(source)
        self.assertEqual(count, 0)
        self.assertEqual(updated, source)

    def test_windows_create_wide_string(self) -> None:
        source = 'window.Create(L"depthvibe", origin, size);'
        updated, count = replace_windows_window_title(source)
        self.assertEqual(count, 1)
        self.assertEqual(updated, 'window.Create(L"DepthVibe", origin, size);')

    def test_windows_create_narrow_string(self) -> None:
        source = 'window.Create("depthvibe", origin, size);'
        updated, count = replace_windows_window_title(source)
        self.assertEqual(count, 1)
        self.assertEqual(updated, 'window.Create("DepthVibe", origin, size);')

    def test_windows_create_and_show_wide_string(self) -> None:
        source = 'window.CreateAndShow(L"depthvibe", origin, size);'
        updated, count = replace_windows_window_title(source)
        self.assertEqual(count, 1)
        self.assertEqual(updated, 'window.CreateAndShow(L"DepthVibe", origin, size);')

    def test_windows_title_replacement_is_idempotent(self) -> None:
        source = 'window.Create(L"DepthVibe", origin, size);'
        updated, count = replace_windows_window_title(source)
        self.assertEqual(count, 1)
        self.assertEqual(updated, source)

    def test_windows_impeller_falls_back_to_skia(self) -> None:
        source = (
            '#include <flutter/dart_project.h>\n'
            'flutter::DartProject project(L"data");\n'
            'FlutterWindow window(project);'
        )
        updated, count = disable_windows_impeller(source)
        self.assertEqual(count, 1)
        self.assertIn(
            'project.set_impeller_switch(flutter::ImpellerSwitch::Disabled);',
            updated,
        )

    def test_windows_impeller_setting_is_idempotent(self) -> None:
        source = (
            'flutter::DartProject project(L"data");\n'
            'project.set_impeller_switch(flutter::ImpellerSwitch::Disabled);'
        )
        updated, count = disable_windows_impeller(source)
        self.assertEqual(count, 0)
        self.assertEqual(updated, source)

    def test_linux_impeller_falls_back_to_skia(self) -> None:
        source = (
            'g_autoptr(FlDartProject) project = fl_dart_project_new();\n'
            'view = fl_view_new(project);'
        )
        updated, count = disable_linux_impeller(source)
        self.assertEqual(count, 1)
        self.assertIn(
            'fl_dart_project_set_enable_impeller(project, FALSE);',
            updated,
        )


if __name__ == "__main__":
    unittest.main()
